/**
 * @name Insecure file/bucket operations in s3fs
 * @description User-controlled paths flowing to S3 operations without proper validation
 * @kind path-problem
 * @problem.severity high
 * @id py/s3fs-insecure-operations
 * @tags security
 *        external/cwe/cwe-022
 *        external/cwe/cwe-200
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module S3fsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for s3fs specific operations that take bucket/path arguments
    exists(API::CallNode call |
      call = API::moduleImport("s3fs").getMember("S3FileSystem").getMember(["open", "read", "write", "delete", "rm", "rmdir", "mkdir", "makedirs", "exists", "info", "ls", "walk", "glob", "find"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module S3fsFlow = TaintTracking::Global<S3fsConfig>;
import S3fsFlow::PathGraph

from S3fsFlow::PathNode source, S3fsFlow::PathNode sink
where S3fsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure S3 operation from $@.", source.getNode(), "user input"
